/**
 * Billing-period arithmetic: where a period ends, what a full period costs and
 * how much of it is left when something changes in the middle.
 *
 * All calendar maths is done in UTC, the zone every `IsoTimestamp` is stored in.
 */
import type { BillingInterval } from "@/types/billing";

const DAY_MS = 24 * 60 * 60 * 1000;

/** Months covered by one period of the interval. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Same day-of-month and time of day `months` later, clamped to the last day of
 * the target month when it is shorter (31 January + 1 → 28 February).
 */
export function addMonthsClamped(start: Date, months: number): Date {
  const year = start.getUTCFullYear();
  const month = start.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  return new Date(
    Date.UTC(
      year,
      month,
      Math.min(start.getUTCDate(), lastDay),
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** The end of the period that starts at `start`. */
export function periodEndFrom(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsInInterval(interval));
}

/** Price per seat per month × seats × months in the period, in cents. */
export function fullPeriodCharge(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/** Whole or started days from `at` to the period end; zero once it is reached. */
export function daysLeftInPeriod(at: Date, periodEnd: Date): number {
  const remaining = periodEnd.getTime() - at.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / DAY_MS);
}

/** Whole days between the period's start and end, rounded, at least one. */
export function daysInPeriod(periodStart: Date, periodEnd: Date): number {
  return Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / DAY_MS),
  );
}

/**
 * The share of `fullAmountCents` still owed for a change made at `at`: scaled
 * by days left over days in the period, rounded down to whole cents.
 */
export function prorate(
  fullAmountCents: number,
  at: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  if (fullAmountCents <= 0) return 0;

  const total = daysInPeriod(periodStart, periodEnd);
  const left = Math.min(daysLeftInPeriod(at, periodEnd), total);
  return Math.floor((fullAmountCents * left) / total);
}

