  let sequence = (await invoiceRepo.countInvoices(orgId)) + 1;
  let number = formatInvoiceNumber(sequence);

  while ((await invoiceRepo.findInvoiceByNumber(orgId, number)) !== null) {
    sequence += 1;
    number = formatInvoiceNumber(sequence);
  }

  return number;
}

function formatInvoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(5, "0")}`;
}

