/**
 * Moves every live subscription's period on, invoicing each renewed paid
 * period, and ends cancellations whose date has come.
 *
 * Must call (do not reimplement): emit, getPlanLimits, issueInvoice
 */
import { getPlanLimits } from "@/config/plan-limits";
import { fullPeriodCharge, periodEndFrom } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Subscriptions read per page; the job pages until every workspace is seen. */
const PAGE_SIZE = 100;

/** Where a cancelled subscription lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * The renewal sweep. Replay-safe by construction: a renewed period always
 * ends after `now`, an ended cancellation is no longer `canceled`, and a
 * renewal invoice is never written twice for the same period — so a second
 * run at the same instant finds nothing to do.
 *
 * `trialing` and `past_due` subscriptions are not this job's business; the
 * trial-expiry job owns the former.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
