import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { listActivity } from "@/server/services/activity-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("scratch", () => {
  it("renews, invoices, cancels", async () => {
    const t = await createTenant("scr", "starter");
    const events: unknown[] = [];
    const off = subscribe("billing.invoice_issued", (p) => { events.push(p); });
    await subscriptionRepo.updateSubscription(t.org.id, {
      status: "active", currentPeriodStart: "2026-01-31T10:00:00.000Z", currentPeriodEnd: "2026-02-28T10:00:00.000Z" as never,
    });
    await subscriptionRepo.updateSeatCount(t.org.id, 3);
    const now = new Date("2026-04-30T12:00:00.000Z");
    const r1 = await runBillingRenewalJob(now);
    const r2 = await runBillingRenewalJob(now);
    console.log(r1, r2);
    const sub = await subscriptionRepo.findSubscription(t.org.id);
    console.log(sub);
    const inv = await billingService.listInvoices(t.actors.owner, t.org.id);
    console.log(inv);
    console.log(events.length);
    const act = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["billing.invoice_issued"], limit: 50, cursor: null } as never);
    console.log(act.items.length, act.items[0]);
    const n = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.owner, unreadOnly: false, kind: ["invoice_issued"], limit: 50, cursor: null } as never);
    console.log(n.items.length, n.items[0]);

    // proration: add seats
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-05-13T14:00:00.000Z")); // period 04-28T10 -> 05-28T10 (30 days); left 14d20h -> 15
    await billingService.updateSeats(t.actors.owner, { orgId: t.org.id, seats: 5 });
    await billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "growth", interval: "monthly" });
    vi.useRealTimers();
    console.log((await billingService.listInvoices(t.actors.owner, t.org.id)).slice(0, 2));

    await billingService.cancelSubscription(t.actors.owner, { orgId: t.org.id, cancelImmediately: false });
    const plans: unknown[] = [];
    const off2 = subscribe("billing.plan_changed", (p) => { plans.push(p); });
    await runBillingRenewalJob(new Date("2026-08-01T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2026-08-01T00:00:00.000Z"));
    console.log(plans, await subscriptionRepo.findSubscription(t.org.id));
    console.log((await billingService.listInvoices(t.actors.owner, t.org.id)).length);
    off(); off2();
    await orgRepo.archiveOrg(t.org.id);
    expect(true).toBe(true);
  });
});
